import{b as s,O as a,g as e,j as i}from"./chunks/framework.DSt9LnBW.js";const k=JSON.parse('{"title":"Locust 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"performance/locust/intro/what-is-locust/index.md","filePath":"性能测试/2.Locust/1.入门篇/01.Locust是什么.md","lastUpdated":1790261034000}'),n={name:"performance/locust/intro/what-is-locust/index.md"};function d(r,t,o,l,p,h){return a(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="locust-是什么" tabindex="-1">Locust 是什么 <a class="header-anchor" href="#locust-是什么" aria-label="Permalink to &quot;Locust 是什么&quot;">​</a></h1><blockquote><p>认识 Locust，搞懂它和 JMeter 的根本区别——用 Python 代码描述用户行为。先建立正确的认知，后面写脚本才不会别扭。</p></blockquote><h2 id="一句话讲清楚" tabindex="-1">一句话讲清楚 <a class="header-anchor" href="#一句话讲清楚" aria-label="Permalink to &quot;一句话讲清楚&quot;">​</a></h2><p><strong>Locust（蝗虫）是开源的压测工具——你用 Python 代码描述&quot;用户会做什么&quot;，它启动成千上万个虚拟用户去执行，然后告诉你系统扛不扛得住。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你定义：50 个用户，每人做&quot;登录 → 查商品 → 加购物车&quot;</span></span>
<span class="line"><span>Locust 干：启动 50 个协程，按你说的流程反复发请求，记录每次耗时</span></span>
<span class="line"><span>你得到：</span></span>
<span class="line"><span>  - 每秒能处理多少请求（RPS）</span></span>
<span class="line"><span>  - 响应时间分布（P50/P95/P99）</span></span>
<span class="line"><span>  - 有没有报错</span></span>
<span class="line"><span>  - 加到多少人系统开始扛不住</span></span></code></pre></div><p>官网对它的一句话概括：</p><blockquote><p>An open source load testing tool. Define user behaviour with Python code, and swarm your system with millions of simultaneous users.</p><p>（一款开源负载测试工具。用 Python 定义用户行为，再让数百万的并发用户涌向你的系统。）</p></blockquote><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>开发语言</td><td>Python</td></tr><tr><td>当前版本</td><td>2.46.6（本教程以此为准）</td></tr><tr><td>Python 要求</td><td><strong>3.11 及以上</strong></td></tr><tr><td>许可</td><td>MIT，商用免费</td></tr><tr><td>官方文档</td><td><a href="https://docs.locust.io/en/stable/" target="_blank" rel="noreferrer">https://docs.locust.io/en/stable/</a></td></tr></tbody></table><h2 id="和-jmeter-的根本区别" tabindex="-1">和 JMeter 的根本区别 <a class="header-anchor" href="#和-jmeter-的根本区别" aria-label="Permalink to &quot;和 JMeter 的根本区别&quot;">​</a></h2><p>两者都能压测 HTTP，但<strong>脚本形态不同</strong>，这是所有差异的源头。</p><table tabindex="0"><thead><tr><th>维度</th><th>Locust</th><th>JMeter</th></tr></thead><tbody><tr><td>脚本形式</td><td><code>.py</code> 代码</td><td>GUI 操作，存成 <code>.jmx</code>（XML）</td></tr><tr><td>并发模型</td><td>协程（gevent）</td><td>线程</td></tr><tr><td>单机并发能力</td><td>通常更高</td><td>通常更低</td></tr><tr><td>写复杂逻辑</td><td>就是写 Python，<code>if</code>/<code>for</code>/函数随便用</td><td>堆控制器、提取器、脚本元件</td></tr><tr><td>代码审查</td><td>Git diff 清晰，能 Review</td><td>XML 难读难 diff</td></tr><tr><td>复用业务代码</td><td>直接 <code>import</code> 现有加签/加密逻辑</td><td>靠 Groovy 或外部 jar</td></tr><tr><td>上手曲线</td><td>会 Python 就很快</td><td>界面友好，非开发人员友好</td></tr><tr><td>协议覆盖</td><td>HTTP 为主，其他靠 Python 库扩展</td><td>插件多，协议面更广</td></tr><tr><td>报告</td><td>Web 实时看 + CSV/HTML 导出</td><td>监听器与 HTML 报告很成熟</td></tr></tbody></table><p>同一个&quot;登录后查商品&quot;，两种写法对比：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Locust：就是一个普通 Python 类，能 import 项目里的任何东西</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> locust </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HttpUser, task, between</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ShopUser</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HttpUser</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    wait_time </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> between(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    @task</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> products</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.client.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/api/products&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- JMeter：本质是配置文件，逻辑靠元件堆出来 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ThreadGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stringProp</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ThreadGroup.num_threads&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;50&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stringProp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ThreadGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><blockquote><p><strong>别急着站队</strong>：功能对不对用 <code>pytest</code>，扛不扛得住用 Locust 或 JMeter。已有 JMeter 体系就继续用；团队 Python 熟、要写复杂逻辑或流式接口，Locust 更顺手。选型对比放在实战篇最后一章。</p></blockquote><h2 id="关键点-协程为什么能省机器" tabindex="-1">关键点：协程为什么能省机器 <a class="header-anchor" href="#关键点-协程为什么能省机器" aria-label="Permalink to &quot;关键点：协程为什么能省机器&quot;">​</a></h2><p>JMeter 一个用户占一个<strong>线程</strong>，线程由操作系统调度，几千个线程光是上下文切换就够 CPU 忙的。</p><p>Locust 一个用户是一个<strong>协程（greenlet）</strong>，由 gevent 在用户态调度。压测脚本 99% 的时间都在等网络 IO，协程正好擅长这个——等 IO 的时候把 CPU 让给别人，切换成本极低。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>线程模型：50 用户 = 50 个 OS 线程 → 内存大、切换贵</span></span>
<span class="line"><span>协程模型：50 用户 = 50 个 greenlet → 内存小、切换几乎无成本</span></span></code></pre></div><p>所以同样一台机器，Locust 通常能比 JMeter 压出更高的并发。<strong>但瓶颈终究在被测服务</strong>，工具只是降低&quot;压测机自己先撑不住&quot;的概率。</p><blockquote><p>真到单机压不动的时候，Locust 还有两招：换 <code>FastHttpUser</code>（官方称最高提升 5~6 倍）、用 <code>--processes</code> 多进程或部署成分布式。这部分放在场景篇的<a href="/performance/locust/scenarios/client-performance/">单机压不上去怎么办</a>。</p></blockquote><h2 id="三个要记住的边界" tabindex="-1">三个要记住的边界 <a class="header-anchor" href="#三个要记住的边界" aria-label="Permalink to &quot;三个要记住的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>它是</th><th>它不是</th></tr></thead><tbody><tr><td>请求发送器（协议层）</td><td>浏览器（不执行 JS，不渲染页面）</td></tr><tr><td>协程模拟并发</td><td>真实用户在操作</td></tr><tr><td>Python 编写的工具，HTTP 一流</td><td>原生协议覆盖广（gRPC/MQTT 等需额外组件）</td></tr><tr><td>适合接口、微服务、AI 接口压测</td><td>适合百万级硬件压测（需大量 worker 协调）</td></tr><tr><td>提供 RPS、响应时间、错误率</td><td>自带断言框架与漂亮报告（要自己接 pytest/Allure 或导出后处理）</td></tr></tbody></table><blockquote><p>一句话：<strong>Locust 管&quot;扛不扛得住、快不快、稳不稳&quot;；&quot;答得对不对&quot;不是它的活。</strong></p></blockquote><h2 id="教程指南" tabindex="-1">教程指南 <a class="header-anchor" href="#教程指南" aria-label="Permalink to &quot;教程指南&quot;">​</a></h2><p>六个篇章，从装环境一路到能独立完成一次压测：</p><table tabindex="0"><thead><tr><th>篇章</th><th>目标</th><th>你会学到</th></tr></thead><tbody><tr><td><strong><a href="/performance/locust/intro/what-is-locust/">入门篇</a></strong></td><td>跑通第一个脚本</td><td>安装、第一个 locustfile、Web UI、命令行</td></tr><tr><td><strong><a href="/performance/locust/core/user-and-tasks/">核心篇</a></strong></td><td>能独立写脚本</td><td>User/任务、等待时间、请求、断言、报告归并、TaskSet、事件钩子</td></tr><tr><td><strong><a href="/performance/locust/scenarios/load-shape/">场景篇</a></strong></td><td>会设计压测</td><td>负载形状、阶梯加压、浪涌与稳定性、分布式、压不上去怎么办</td></tr><tr><td><strong><a href="/performance/locust/advanced/test-data/">进阶篇</a></strong></td><td>融入工程体系</td><td>测试数据、流式接口、pytest 集成、调试排错、监控与 CI</td></tr><tr><td><strong><a href="/performance/locust/practice/login-and-skeleton/">实战篇</a></strong></td><td>完整打一次压测</td><td>打 testing-online：登录态、业务比例、阶梯压测、报告解读、选型</td></tr><tr><td><strong><a href="/performance/locust/llm/basics/">大模型压测篇</a></strong></td><td>压 AI 接口</td><td>TTFT、tokens/s、429、空响应，流式与官方 OpenAIUser</td></tr></tbody></table><p>名词都给了中英对照，例如「用户类 User」「任务 task」「等待时间 wait_time」，方便对着官方英文文档看。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>Locust 是什么</strong>：Python 写的开源压测工具，用代码描述用户行为</li><li><strong>核心差异</strong>：脚本是 <code>.py</code> 代码，并发靠协程——所以更省机器、更好写复杂逻辑、更好做 Code Review</li><li><strong>别站队</strong>：功能正确性归 pytest，容量与稳定性归 Locust/JMeter</li><li><strong>版本要求</strong>：Python ≥ 3.11，官方文档只有英文</li><li><strong>本教程被测项目</strong>：testing-online，API 在 <code>localhost:3001</code>，Bearer Token 鉴权</li></ul><p>下一章把环境装好，准备动手。</p>`,31)])])}const g=s(n,[["render",d]]);export{k as __pageData,g as default};
